package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils.indexOfAnyBut
 */
public class StringUtils_indexOfAnyBut_TriageGen0Test {

    private static final int INDEX_NOT_FOUND = -1;

    @Test
    public void testIndexOfAnyBut_NullStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(null, "abc"));
    }

    @Test
    public void testIndexOfAnyBut_EmptyStr() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NullSearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", null));
    }

    @Test
    public void testIndexOfAnyBut_EmptySearchChars() {
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", ""));
    }

    @Test
    public void testIndexOfAnyBut_FoundAtFirstIndex() {
        // 'z' is not in "abc"
        assertEquals(0, StringUtils.indexOfAnyBut("zabc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_FoundInMiddle() {
        // 'z' is not in "abc", found at index 2
        assertEquals(2, StringUtils.indexOfAnyBut("abzcd", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_FoundAtLastIndex() {
        // 'z' is not in "abc", found at index 4
        assertEquals(4, StringUtils.indexOfAnyBut("abcdz", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NotFound() {
        // All characters in "abc" are present in "search"
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", "abc"));
        // All characters in "aabbcc" are present in "abc"
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aabbcc", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_SingleCharSearch() {
        assertEquals(0, StringUtils.indexOfAnyBut("b", "a"));
        assertEquals(1, StringUtils.indexOfAnyBut("ab", "a"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("a", "a"));
    }

    @Test
    public void testIndexOfAnyBut_CaseSensitivity() {
        // 'A' is not in "abc"
        assertEquals(0, StringUtils.indexOfAnyBut("Aabc", "abc"));
        // 'a' is in "abc", but 'B' is not
        assertEquals(1, StringUtils.indexOfAnyBut("aBcd", "abc"));
    }
}
